	/**
	 * Internal helper method to load the root 
	 * 
	 * @param		id	UUID
	 * @return		Employee
	 */
	protected Employee load( UUID id ) throws ProcessingException {
		employee = EmployeeService.getEmployeeInstance().getEmployee( new EmployeeFetchOneSummary(id) );	
		return employee;
	}


